# verify bonding topology unchanged vs assembled
import numpy as np
def read(f):
    L=open(f).read().split('\n')[2:]; S=[];X=[]
    for l in L:
        p=l.split()
        if len(p)==4: S.append(p[0]); X.append([float(v) for v in p[1:]])
    return S,np.array(X)
def bonds(S,X):
    r={'H':0.32,'C':0.75,'O':0.66,'F':0.57,'Cr':1.3}
    D=np.linalg.norm(X[:,None]-X[None],axis=2); b=set()
    for i in range(len(S)):
        for j in range(i+1,len(S)):
            if D[i,j]<1.2*(r[S[i]]+r[S[j]]): b.add((i,j))
    return b
S,X0=read('assembled.xyz'); _,X1=read('ff_opt.xyz')
b0=bonds(S,X0); b1=bonds(S,X1)
print(len(b0),len(b1),"lost",b0-b1,"new",b1-b0)
EOF

